{
  "name": "color-check-cli",
  "version": "0.1.0",
  "description": "CLI that detects terminal color support before printing colored text",
  "type": "module",
  "bin": {
    "color-check": "./bin/cli.js"
  },
  "exports": {
    ".": "./src/index.js",
    "./color-support": "./src/color-support.js"
  },
  "files": [
    "bin",
    "src"
  ],
  "engines": {
    "node": ">=18"
  },
  "scripts": {
    "start": "node ./bin/cli.js",
    "test": "node --test"
  },
  "license": "MIT"
}

export const ColorLevel = {
  None: 0,
  Basic: 1,
  Ansi256: 2,
  TrueColor: 3,
}

function hasFlag(name, env) {
  return Object.prototype.hasOwnProperty.call(env, name)
}

function parseForceColor(env) {
  if (!hasFlag("FORCE_COLOR", env)) return undefined
  const value = env.FORCE_COLOR
  if (value === "false" || value === "0") return ColorLevel.None
  if (value === "true" || value === "") return ColorLevel.Basic
  if (value === "2") return ColorLevel.Ansi256
  if (value === "3") return ColorLevel.TrueColor
  return ColorLevel.Basic
}

export function detectColorLevel({
  env = process.env,
  isTTY = Boolean(process.stdout && process.stdout.isTTY),
  platform = process.platform,
} = {}) {
  const forced = parseForceColor(env)
  if (forced !== undefined) return forced

  if (hasFlag("NO_COLOR", env)) return ColorLevel.None
  if (env.TERM === "dumb") return ColorLevel.None

  if (env.COLORTERM === "truecolor" || env.COLORTERM === "24bit") {
    return ColorLevel.TrueColor
  }

  if (env.TERM_PROGRAM === "iTerm.app" && /^3/.test(env.TERM_PROGRAM_VERSION || "")) {
    return ColorLevel.TrueColor
  }

  if (/(?:-|\b)(?:256|16m)color\b/i.test(env.TERM || "")) {
    return ColorLevel.Ansi256
  }

  if (isTTY) return ColorLevel.Basic
  if (platform === "win32" && env.ANSICON) return ColorLevel.Basic
  if (platform === "win32" && /^9/.test(env.ConEmuANSI || "")) return ColorLevel.Basic

  return ColorLevel.None
}

export function supportsColor(options) {
  return detectColorLevel(options) > ColorLevel.None
}

import { ColorLevel, detectColorLevel } from "./color-support.js"

const CODES = {
  reset: 0,
  bold: 1,
  red: 31,
  green: 32,
  yellow: 33,
  blue: 34,
  magenta: 35,
  cyan: 36,
  gray: 90,
}

function wrap(code, text) {
  return `\u001B[${code}m${text}\u001B[0m`
}

export function createColors(level = detectColorLevel()) {
  const colors = {}

  for (const [name, code] of Object.entries(CODES)) {
    colors[name] =
      level > ColorLevel.None
        ? (text) => wrap(code, String(text))
        : (text) => String(text)
  }

  if (level >= ColorLevel.Ansi256) {
    colors.ansi256 = (code, text) => wrap(`38;5;${code}`, String(text))
  } else {
    colors.ansi256 = (code, text) => String(text)
  }

  if (level >= ColorLevel.TrueColor) {
    colors.rgb = (r, g, b, text) => wrap(`38;2;${r};${g};${b}`, String(text))
  } else {
    colors.rgb = (r, g, b, text) => String(text)
  }

  colors.level = level
  colors.supportsColor = level > ColorLevel.None

  return colors
}

#!/usr/bin/env node
import { detectColorLevel, ColorLevel } from "../src/color-support.js"
import { createColors } from "../src/colors.js"

const LEVEL_NAMES = {
  [ColorLevel.None]: "none",
  [ColorLevel.Basic]: "basic (16 colors)",
  [ColorLevel.Ansi256]: "ansi256",
  [ColorLevel.TrueColor]: "truecolor (16m)",
}

const args = new Set(process.argv.slice(2))
const json = args.has("--json")
const level = detectColorLevel()
const c = createColors(level)

if (json) {
  process.stdout.write(
    JSON.stringify({ level, supportsColor: level > ColorLevel.None }) + "\n",
  )
} else if (args.has("--demo") || args.has("--demo".slice(0))) {
  console.log(c.red("red"), c.green("green"), c.blue("blue"))
  console.log(c.ansi256(208, "ansi256"), c.rgb(255, 128, 0, "truecolor"))
  console.log(`level: ${c.bold(LEVEL_NAMES[level])}`)
} else {
  const status = c.supportsColor ? c.green("yes") : c.yellow("no")
  console.log(`Color support: ${status} (${LEVEL_NAMES[level]})`)
}

